define(['uiComponent','mage/template','prototype'],function(Component,mageTemplate){return Component.extend({initialize:function(config){let htmlId=config.htmlId;let arrayRowX='arrayRow'+htmlId;let addToEndBtnX='addToEndBtn'+htmlId;let html=config.html;let templateValuesOrig=config.templateValues;let arrayRows=config.arrayRows;window[arrayRowX]={template:mageTemplate(html),add:function(rowData,insertAfterId){let templateValues;if(rowData){templateValues=rowData;}else{let d=new Date();templateValues={option_extra_attrs:{},_id:'_'+d.getTime()+'_'+d.getMilliseconds()};for(let prop in templateValuesOrig){if(templateValuesOrig.hasOwnProperty(prop)){let columnName=templateValuesOrig[prop];templateValues[columnName]='';}}}
if(insertAfterId){Element.insert($(insertAfterId),{after:this.template(templateValues)});}else{Element.insert($('addRow'+htmlId),{bottom:this.template(templateValues)});}
if(rowData){let rowInputElementNames=Object.keys(rowData.column_values);for(let key in rowInputElementNames){if(rowInputElementNames.hasOwnProperty(key)){if($(rowInputElementNames[key])){$(rowInputElementNames[key]).value=rowData.column_values[rowInputElementNames[key]];}}}}
if(config.isAddAfter!=0){Event.observe('addAfterBtn'+templateValues._id,'click',this.add.bind(this,false,templateValues._id));}},del:function(rowId){$(rowId).remove();}};Event.observe(addToEndBtnX,'click',window[arrayRowX].add.bind(window[arrayRowX],false,false));for(let key in arrayRows){if(arrayRows.hasOwnProperty(key)){window[arrayRowX].add(arrayRows[key]);}}
if(config.disabled!=0){toggleValueElements({checked:true},$('grid'+htmlId).parentNode);}}});});